import { useSelector, useDispatch } from 'react-redux';
import { formaterContratosDataTable } from '../../../utils/formaterDataTable';
import { useEffect, useRef, useState } from 'react';
import { SearchOutlined } from '@ant-design/icons';
import { Button, Input, Space, Table } from 'antd';

function TableContratos() {
    const [elementsData, setElementsData] = useState([]);
    const fileContratos = useSelector((state) => state.config.routerFiles.contratos);
    useEffect(() => {
        if (fileContratos) {
            formaterContratosDataTable(fileContratos).then((data) => {
                console.log("data", data);
                setElementsData(data);
            })
        }
    }, [fileContratos]);

    const [searchText, setSearchText] = useState('');
    const [searchedColumn, setSearchedColumn] = useState('');
    const searchInput = useRef(null);
    const handleSearch = (selectedKeys, confirm, dataIndex) => {
        confirm();
        setSearchText(selectedKeys[0]);
        setSearchedColumn(dataIndex);
    };
    const handleReset = clearFilters => {
        clearFilters();
        setSearchText('');
    };
    const getColumnSearchProps = dataIndex => ({
        filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters, close }) => (
            <div style={{ padding: 8 }} onKeyDown={e => e.stopPropagation()}>
                <Input
                    ref={searchInput}
                    placeholder={`Search ${dataIndex}`}
                    value={selectedKeys[0]}
                    onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
                    onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
                    style={{ marginBottom: 8, display: 'block' }}
                />
                <Space>
                    <Button
                        type="primary"
                        onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
                        icon={<SearchOutlined />}
                        size="small"
                        style={{ width: 90 }}
                    >
                        Buscar
                    </Button>
                    <Button
                        onClick={() => clearFilters && handleReset(clearFilters)}
                        size="small"
                        style={{ width: 90 }}
                    >
                        Limpiar
                    </Button>
                </Space>
            </div>
        ),
        filterIcon: filtered => <SearchOutlined style={{ color: filtered ? '#1677ff' : undefined }} />,
        onFilter: (value, record) =>
            record[dataIndex].toString().toLowerCase().includes(value.toLowerCase()),
        filterDropdownProps: {
            onOpenChange(open) {
                if (open) {
                    setTimeout(() => {
                        var _a;
                        return (_a = searchInput.current) === null || _a === void 0 ? void 0 : _a.select();
                    }, 100);
                }
            },
        },
        render: text => (text),
    });

    const uniqueAreas = [...new Set(elementsData.map(item => item.area))]; // Obtener áreas únicas

    const columns = [
        {
            title: 'Área',
            dataIndex: 'area',
            key: 'area',
            filters: uniqueAreas.map(area => ({ text: area, value: area })), 
            onFilter: (value, record) => record.area === value,
            sorter: (a, b) => a.area.localeCompare(b.area),
            sortDirections: ['descend', 'ascend'],
        },
        Object.assign(
            { title: 'Número', dataIndex: 'numero', key: 'numero' },
            getColumnSearchProps('numero'),
        ),
        Object.assign(
            { title: 'Año', dataIndex: 'ano', key: 'ano' },
            getColumnSearchProps('ano'),
            {
                sorter: (a, b) => parseInt(a.ano, 10) - parseInt(b.ano, 10),
                sortDirections: ['descend', 'ascend'],
            },
        ),
        Object.assign(
            { title: 'Objeto (Breve resumen del contrato)', dataIndex: 'resumen', key: 'resumen', width: '40%' },
            getColumnSearchProps('resumen'),
        ),
        Object.assign(
            { title: 'Fecha de susbcripción', dataIndex: 'fechaSusbscripcion', key: 'fechaSusbscripcion' },
            getColumnSearchProps('fechaSusbscripcion'),
        ),
        Object.assign(
            { title: 'Inicio', dataIndex: 'inicio', key: 'inicio' },
            getColumnSearchProps('inicio'),
        ),
        Object.assign(
            { title: 'Fin prorroga', dataIndex: 'finProrroga', key: 'finProrroga' },
            getColumnSearchProps('finProrroga'),
        ),
        Object.assign(
            { title: 'Valor contrato', dataIndex: 'valorContrato', key: 'valorContrato' },
            getColumnSearchProps('valorContrato'),
        ),
        Object.assign(
            { title: 'Total Contrato', dataIndex: 'totalContrato', key: 'totalContrato' },
            getColumnSearchProps('totalContrato'),
        ),
        Object.assign(
            { title: 'Ejecución real', dataIndex: 'ejecucionReal', key: 'ejecucionReal' },
            getColumnSearchProps('ejecucionReal'),
        ),
        Object.assign(
            { title: 'Días Vence', dataIndex: 'diasVence', key: 'diasVence' },
            getColumnSearchProps('diasVence'),
        ),
    ];
    return (
        <>
            <h1>Contratos</h1>
            {elementsData &&
                <div style={{overflowX: 'auto'}}>
                    <Table 
                    columns={columns} 
                    dataSource={elementsData} 
                    scroll={{ x: 2300, y: 500 }} 
                    pagination={{ pageSize: 20}} 
                    />
                </div>
            }
        </>
    );
}

export default TableContratos;
