import { fetchSheet } from "./getConfigSheet";
import Papa from 'papaparse';


export async function formaterContratosDataTable(fileDataContratos) {
    const contratosUrl = fileDataContratos.urlPublic.replace('?', `?gid=${fileDataContratos.gid}&`)
    const contratosSheet = await fetchSheet(contratosUrl)
    const result = Papa.parse(contratosSheet, {
        header: false,
        skipEmptyLines: false,
        delimiter: ",",
        quoteChar: '"'
    });
    let dataTableJson = []
    result.data.forEach((row, index) => {
        if (index > 0) {
                dataTableJson.push({
                    key: index,
                    area: row[0],
                    numero: row[1],
                    ano: row[2],
                    nombre: row[3],
                    resumen: row[4],
                    fechaSusbscripcion: row[5],
                    inicio: row[6],
                    finProrroga: row[7],
                    valorContrato: row[8],
                    ValoresAdicionales: row[9],
                    totalContrato: row[10],
                    ejecucionReal: row[11],
                    diasVence: row[12]
                })
            }
    })

    return dataTableJson
}